{
  "families": [
    {
      "family": "pipelined",
      "ranges": [
        {"param": "data_width", "low": 12, "high": 20, "choices": null},
        {"param": "n_iter", "low": 10, "high": 20, "choices": null},
        {"param": "angle_guard", "low": -2, "high": 4, "choices": null},
        {"param": "frac_guard", "low": 0, "high": 4, "choices": null},
        {"param": "rounding", "low": null, "high": null, "choices": ["trunc", "round"]}
      ],
      "budget_share": 60,
      "why": "Pipelined gives 1 result/cycle, so throughput equals Fmax; only this family can plausibly reach 400 MSPS. Ranges cover the accuracy boundary (W>=14, N>=13) and the area/Fmax trade-off."
    },
    {
      "family": "pipelined_m",
      "ranges": [
        {"param": "data_width", "low": 12, "high": 20, "choices": null},
        {"param": "n_iter", "low": 10, "high": 20, "choices": null},
        {"param": "angle_guard", "low": -2, "high": 4, "choices": null},
        {"param": "frac_guard", "low": 0, "high": 4, "choices": null},
        {"param": "rounding", "low": null, "high": null, "choices": ["trunc", "round"]},
        {"param": "m", "low": 2, "high": 8, "choices": null}
      ],
      "budget_share": 40,
      "why": "Pipelined_m also gives 1 result/cycle but with fewer registers; it may offer a different area/Fmax trade-off. Search m to find the best balance."
    }
  ],
  "rationale": "The throughput constraint of 400 MSPS single-lane requires one result per cycle at >=400 MHz, which only pipelined families can plausibly achieve. Iterative and unrolled_k produce one result every several cycles and would need impractically high clock rates. Accuracy constraint of 12 bits requires data_width >= 14 and n_iter >= ~13. We search pipelined and pipelined_m over data_width 12..20, n_iter 10..20, full guard ranges, both rounding modes, and m 2..8 for pipelined_m, to map the trade-off between LUTs, Fmax, and accuracy. Budget split favours pipelined as it has the shortest critical path and best chance of meeting 400 MHz."
}
